var i=168;var a=[{id:`cooking-168-01`,theoryId:168,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why can over-blending starchy potato soup create a gluey texture?`,ua:`Чому надмірне збивання картопляного супу може зробити його клейким?`},explanation:{en:`High shear can release starch and make some potato preparations gummy.`,ua:`Сильне механічне подрібнення може вивільняти крохмаль і робити картопляні страви клейкими.`},options:[{id:`a`,text:{en:`Potatoes contain no starch`,ua:`У картоплі немає крохмалю`}},{id:`b`,text:{en:`Mechanical damage releases excess gelatinized starch`,ua:`Механічне руйнування вивільняє забагато клейстеризованого крохмалю`}},{id:`c`,text:{en:`Blending destroys all water molecules`,ua:`Блендер руйнує всі молекули води`}}],answer:{optionIds:[`b`]}},{id:`cooking-168-02`,theoryId:168,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Soup thickness can be changed by adding liquid in controlled increments.`,ua:`Густоту супу можна змінювати поступовим додаванням рідини.`},explanation:{en:`Gradual dilution is easier to control than adding a large volume at once.`,ua:`Поступове розбавлення контролювати простіше, ніж одночасне додавання великого об’єму.`},answer:{value:!0}},{id:`cooking-168-03`,theoryId:168,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match soup texture faults to likely causes.`,ua:`Поєднайте вади текстури супу з імовірними причинами.`},explanation:{en:`Diagnosing texture starts with ingredient structure and processing.`,ua:`Діагностика текстури починається зі структури продуктів і способу обробки.`},leftItems:[{id:`l1`,text:{en:`Gluey potato soup`,ua:`Клейкий картопляний суп`}},{id:`l2`,text:{en:`Watery vegetable soup`,ua:`Водянистий овочевий суп`}},{id:`l3`,text:{en:`Gritty blended soup`,ua:`Зернистий суп-пюре`}}],rightItems:[{id:`r2`,text:{en:`Too little suspended solid or too much liquid`,ua:`Замало подрібнених частинок або забагато рідини`}},{id:`r3`,text:{en:`Inadequate cooking or blending of ingredients`,ua:`Недостатнє розм’якшення або подрібнення інгредієнтів`}},{id:`r1`,text:{en:`Excessive high-shear blending`,ua:`Надмірне інтенсивне збивання`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-168-04`,theoryId:168,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A vegetable soup is too thick after cooling. What is a controlled fix?`,ua:`Овочевий суп після охолодження став надто густим. Як виправити?`},explanation:{en:`Starches and gels change during cooling; controlled liquid restores serving consistency.`,ua:`Крохмалі та гелі змінюються після охолодження; поступове додавання рідини відновлює консистенцію.`},options:[{id:`a`,text:{en:`Leave at room temperature until it thins`,ua:`Залишити за кімнатної температури, доки розрідне`}},{id:`b`,text:{en:`Reheat safely and add small amounts of suitable liquid`,ua:`Безпечно розігріти та додати трохи відповідної рідини`}},{id:`c`,text:{en:`Add a large amount of raw flour`,ua:`Додати багато сирого борошна`}}],answer:{optionIds:[`b`]}},{id:`cooking-168-05`,theoryId:168,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which hot-soup blending action is unsafe?`,ua:`Яка дія під час збивання гарячого супу небезпечна?`},explanation:{en:`Hot vapor pressure may force off the lid and cause serious burns.`,ua:`Тиск гарячої пари може зірвати кришку та спричинити опіки.`},options:[{id:`a`,text:{en:`Fill a sealed countertop blender to the brim with boiling soup`,ua:`Наповнити герметично закритий блендер киплячим супом доверху`}},{id:`b`,text:{en:`Blend smaller portions with suitable equipment`,ua:`Збивати невеликі порції відповідним обладнанням`}},{id:`c`,text:{en:`Follow blender venting guidance and avoid pressure buildup`,ua:`Дотримуватися вказівок щодо вентиляції кришки та не допускати надлишкового тиску`}}],answer:{optionIds:[`a`]}}];var n={theoryId:168,exercises:a};export{n as default,a as exercises,i as theoryId};